//! Generated by Gemini when given the following prompts:
//!
//! Please generate Zig code for text replacement using the Wu-Manber algorithm. The input is a
//! struct whose field names are the search strings and the value are the replacements. I'm
//! using Zig 0.17.1.
//!
//! Build the shift table at comptime.
const std = @import("std");

/// A zero-allocation, comptime-compiled multi-pattern text replacer.
pub fn ComptimeReplacer(comptime RulesStruct: type) type {
    const struct_info = @typeInfo(RulesStruct).@"struct";
    const pattern_count = struct_info.field_names.len;
    const B = 2; // Block size for hash/shift table

    // Calculate minimum pattern length at compile-time
    const min_len = comptime blk: {
        var len: usize = std.math.maxInt(usize);
        for (struct_info.field_names) |name| {
            if (name.len < B) {
                @compileError("Wu-Manber requires all search keys to be at least as long as the block size (B = 2). Short key found: '" ++ name ++ "'");
            }
            if (len > name.len) len = name.len;
        }
        break :blk len;
    };

    // Precompute lookup tables at compile-time
    const tables = comptime blk: {
        const TableSize = 65536; // 2^16 for B=2 byte pairings

        var shift_table: [TableSize]usize = @splat(min_len - B + 1);
        var hash_table: [TableSize]?usize = @splat(null);
        var next_pattern: [pattern_count]?usize = @splat(null);

        // Build SHIFT table
        for (struct_info.field_names, 0..) |pattern, p_idx| {
            var j: usize = B;
            while (j <= min_len) : (j += 1) {
                const block = pattern[j - B .. j];
                const h = (@as(u16, block[0]) << 8) | block[1];
                const shift_val = min_len - j;
                if (shift_val < shift_table[h]) {
                    shift_table[h] = shift_val;
                }
            }

            // Add pattern pointer into the structural HASH chains using its ending min_len block
            const suffix_block = pattern[min_len - B .. min_len];
            const h = (@as(u16, suffix_block[0]) << 8) | suffix_block[1];

            next_pattern[p_idx] = hash_table[h];
            hash_table[h] = p_idx;
        }

        break :blk .{
            .shift = shift_table,
            .hash = hash_table,
            .next = next_pattern,
        };
    };

    return struct {
        const Self = @This();

        replacements: [pattern_count][]const u8,

        pub fn init(rules: RulesStruct) Self {
            var self: Self = undefined;
            inline for (struct_info.field_names, 0..) |name, i| {
                if (struct_info.field_types[i] != []const u8) {
                    @compileError("All values in the replacement struct must be of type []const u8");
                }
                self.replacements[i] = @field(rules, name);
            }
            return self;
        }

        pub fn replace(self: Self, allocator: std.mem.Allocator, text: []const u8) ![]const u8 {
            // Calculate 125% capacity: text.len + (text.len / 4)
            // Using a safe math check to prevent integer overflow on massive inputs
            const extra_capacity = text.len / 4;
            const initial_capacity = blk: {
                const res, const overflow = @addWithOverflow(text.len, extra_capacity);
                if (overflow != 0) break :blk text.len; // Fallback to raw text length if it overflows
                break :blk res;
            };

            // Initialize ArrayList with pre-allocated 125% capacity headroom
            var result = try std.ArrayList(u8).initCapacity(allocator, initial_capacity);
            errdefer result.deinit(allocator);

            var i: usize = min_len;
            var last_flush_idx: usize = 0;

            while (i <= text.len) {
                const block = text[i - B .. i];
                const h = (@as(u16, block[0]) << 8) | block[1];
                const shift_val = tables.shift[h];

                if (shift_val == 0) {
                    var maybe_p_idx = tables.hash[h];
                    var matched_idx: ?usize = null;
                    var longest_match: usize = 0;
                    const start_pos = i - min_len;

                    while (maybe_p_idx) |p_idx| {
                        const pat = struct_info.field_names[p_idx];

                        if (start_pos + pat.len <= text.len) {
                            if (std.mem.eql(u8, text[start_pos .. start_pos + pat.len], pat)) {
                                if (pat.len > longest_match) {
                                    longest_match = pat.len;
                                    matched_idx = p_idx;
                                }
                            }
                        }
                        maybe_p_idx = tables.next[p_idx];
                    }

                    if (matched_idx) |p_idx| {
                        // Flush preceding unmatched text
                        try result.appendSlice(allocator, text[last_flush_idx..start_pos]);
                        // Append substitution token
                        try result.appendSlice(allocator, self.replacements[p_idx]);

                        // FIX: Advance the window 'i' to end exactly at the next minimum window size
                        // following the matched pattern sequence.
                        last_flush_idx = start_pos + longest_match;
                        i = last_flush_idx + min_len;
                        continue;
                    }

                    i += 1;
                } else {
                    i += shift_val;
                }
            }

            if (last_flush_idx < text.len) {
                try result.appendSlice(allocator, text[last_flush_idx..]);
            }

            return result.toOwnedSlice(allocator);
        }
    };
}
